const D:usize=8;const L:usize=132;
fn put64(o:[*]u8,p:usize,x:i64)void{const b:u64=@bitCast(x);for(0..8)|j|o[p+j]=@truncate(b>>@intCast(8*j));}
export fn two_dimensional_string_matching(input_opt:?[*]const i64,length:usize,output_opt:?[*]u8,capacity:usize)i64{
 if(input_opt==null or length<6 or length>L)return -1;const in=input_opt.?;const rr=in[0];const cc=in[1];const hr=in[2];const wc=in[3];if(rr<1 or rr>8 or cc<1 or cc>8 or hr<1 or hr>rr or wc<1 or wc>cc)return -1;const r:usize=@intCast(rr);const c:usize=@intCast(cc);const h:usize=@intCast(hr);const w:usize=@intCast(wc);if(length!=4+r*c+h*w)return -1;var text:[64]i64=@splat(0);var pat:[64]i64=@splat(0);var p:usize=4;for(0..r*c)|i|{text[i]=in[p];p+=1;if(text[i]<0 or text[i]>3)return -1;}for(0..h*w)|i|{pat[i]=in[p];p+=1;if(pat[i]<0 or pat[i]>3)return -1;}
 var prefix:[D]i64=@splat(0);for(1..h)|i|{var q:usize=@intCast(prefix[i-1]);while(q>0){var equal=true;for(0..w)|j|{if(pat[i*w+j]!=pat[q*w+j])equal=false;}if(equal)break;q=@intCast(prefix[q-1]);}var equal=true;for(0..w)|j|{if(pat[i*w+j]!=pat[q*w+j])equal=false;}if(equal)q+=1;prefix[i]=@intCast(q);}
 var mark:[D*D*D]bool=@splat(false);for(0..r)|tr|{for(0..(c-w+1))|col|{for(0..h)|pr|{var equal=true;for(0..w)|j|{if(text[tr*c+col+j]!=pat[pr*w+j])equal=false;}mark[(tr*D+col)*D+pr]=equal;}}}
 var mr:[D*D]i64=@splat(0);var mc:[D*D]i64=@splat(0);var count:usize=0;for(0..(c-w+1))|col|{var q:usize=0;for(0..r)|tr|{while(q>0 and !mark[(tr*D+col)*D+q])q=@intCast(prefix[q-1]);if(mark[(tr*D+col)*D+q])q+=1;if(q==h){mr[count]=@intCast(tr+1-h);mc[count]=@intCast(col);count+=1;q=@intCast(prefix[h-1]);}}}const bytes=8*(1+2*count);if(output_opt==null or capacity<bytes)return -2;const out=output_opt.?;put64(out,0,@intCast(count));for(0..count)|i|{put64(out,8*(1+2*i),mr[i]);put64(out,8*(2+2*i),mc[i]);}return @intCast(bytes);
}
